        for (const c of content) {
          if (c.type === 'text') summary += 'USER_TEXT: ' + c.text.slice(0, 200).replace(/\n/g, ' ') + ' | ';
          else if (c.type === 'tool_result') {
            let rc = c.content;
            let rs = typeof rc === 'string' ? rc : JSON.stringify(rc);
            summary += 'TOOL_RESULT(' + (c.tool_use_id||'').slice(0,8) + '): ' + (rs||'').slice(0,150).replace(/\n/g,' ') + ' | ';
